import { app,BrowserWindow } from 'electron'
import { readFileSync,writeFileSync } from 'node:fs'
const config=JSON.parse(readFileSync(process.env.MOUSSE_TASK_PICKER_FIXTURE!,'utf8'))
app.setPath('userData',config.userData)
void(async()=>{
await app.whenReady()
const window=new BrowserWindow({show:false,webPreferences:{contextIsolation:true,nodeIntegration:false,sandbox:true}})
const run=async(source:string)=>{const value=await window.webContents.executeJavaScript(`(()=>{try{return{ok:true,value:eval(${JSON.stringify(source)})}}catch(error){return{ok:false,error:String(error)}}})()`);if(!value.ok)throw new Error(source+': '+value.error);return value.value}
const wait=async(source:string)=>{const deadline=Date.now()+5000;while(!await run(source)){if(Date.now()>=deadline)throw new Error('Mounted picker condition failed: '+source);await new Promise(done=>setTimeout(done,20))}}
const check=async(source:string)=>{if(!await run(source))throw new Error('Mounted picker assertion failed: '+source)}
const click=async(text:string)=>{await wait(`[...document.querySelectorAll('button')].some(button=>button.textContent===${JSON.stringify(text)}&&!button.disabled)`);return run(`window.taskFixture.click(${JSON.stringify(text)})`)}
try{
  await window.loadFile(config.html)
  await wait(`!!document.querySelector('select[aria-label="Saved task"] option[value="rpc_durable"]')`)
  const initialCalls=await run('window.taskFixture.calls()')
  await run(`window.taskFixture.set('Saved task','rpc_durable')`)
  await wait(`window.taskFixture.hasButton('Start task on selected device')&&!document.querySelector('select[aria-label="Saved task"]').disabled`)
  await check(`!document.querySelector('textarea')`)
  await click('Refresh task status')
  await wait(`window.taskFixture.calls().filter(c=>c.method==='chats.task.get').length===2&&!document.querySelector('select[aria-label="Saved task"]').disabled`)
  await click('Start task on selected device')
  await wait(`document.body.textContent.includes('Lost Start reply')&&window.taskFixture.hasButton('Retrieve original result')`)
  await check(`!window.taskFixture.hasButton('Start task on selected device')`)
  await click('Refresh task status')
  await wait(`!document.querySelector('select[aria-label="Saved task"]').disabled`)
  await click('Retrieve original result')
  await wait(`document.body.textContent.includes('Verified result · commit')`)
  const durableCalls=await run('window.taskFixture.calls()')
  await click('Next tasks')
  await wait(`!!document.querySelector('select[aria-label="Saved task"] option[value="rpc_failed"]')`)
  await run(`window.taskFixture.set('Saved task','rpc_failed')`)
  await wait(`document.body.textContent.includes('Rejected · failed')`)
  await check(`!window.taskFixture.hasButton('Start task on selected device')&&!window.taskFixture.hasButton('Retrieve original result')`)
  await click('Refresh saved tasks')
  await wait(`!!document.querySelector('select[aria-label="Saved task"] option[value="rpc_durable"]')`)
  await run(`window.taskFixture.set('Saved task','rpc_durable');window.taskFixture.readonly(true)`)
  await wait(`window.taskFixture.hasButton('Retrieve original result')&&!document.querySelector('select[aria-label="Saved task"]').disabled`)
  await click('Retrieve original result')
  await wait(`document.body.textContent.includes('Verified result · commit')`)
  await run(`window.taskFixture.deny()`);await click('Refresh task status')
  await wait(`document.body.textContent.includes('Current membership denied')`)
  await check(`!document.body.textContent.includes('verified-commit')&&!document.querySelector('select[aria-label="Saved task"] option[value="rpc_durable"]')&&!window.taskFixture.hasButton('Retrieve original result')`)
  const pageCalls=await run('window.taskFixture.calls()')
  await run(`window.taskFixture.reset('new')`)
  await wait(`!document.querySelector('select[aria-label="Saved task"]').disabled&&!!document.querySelector('select[aria-label="Task device"] option[value="nod_fixture"]')`)
  await run(`window.taskFixture.set('Device','nod_fixture');window.taskFixture.set('Authorized repository ID','repo-fixture');window.taskFixture.set('Base commit','base-fixture');window.taskFixture.set('Published agent ID on that device','agent-fixture');window.taskFixture.set('Task','ORIGINAL INPUT')`)
  await click('Prepare task')
  await wait(`document.body.textContent.includes('Lost preparation reply')`)
  await check(`document.querySelector('fieldset').disabled`)
  await run(`window.taskFixture.set('Task','MUTATED DISPLAY INPUT')`)
  await click('Retry original preparation')
  await wait(`window.taskFixture.calls().filter(c=>c.method==='chats.assignDevice').length===2&&!document.querySelector('button').disabled`)
  await check(`!window.taskFixture.hasButton('Prepare another task')`)
  await run(`window.taskFixture.set('Task','SECOND MUTATED DISPLAY INPUT')`)
  await click('Retry original preparation')
  await wait(`window.taskFixture.hasButton('Start task on selected device')`)
  await check(`!window.taskFixture.hasButton('Prepare another task')`)
  const prepareCalls=await run(`window.taskFixture.calls().filter(c=>c.method==='chats.assignDevice')`),original=await run('window.taskFixture.prepared()')
  await click('Start task on selected device')
  await wait(`document.body.textContent.includes('Lost Start reply')&&window.taskFixture.hasButton('Retrieve original result')`)
  await check(`!window.taskFixture.hasButton('Prepare another task')`)
  await click('Retrieve original result')
  await wait(`document.body.textContent.includes('Verified result · commit')`)
  await wait(`window.taskFixture.hasButton('Prepare another task')`)
  const beforeNew=await run('window.taskFixture.calls().length')
  await click('Prepare another task')
  await wait(`!!document.querySelector('fieldset')&&!document.querySelector('fieldset').disabled`)
  await check(`window.taskFixture.calls().length===${beforeNew}&&[...document.querySelectorAll('input,textarea')].every(field=>field.value==='')&&document.querySelector('select[aria-label="Task device"]').value===''&&!document.body.textContent.includes('verified-commit')`)
  await run(`window.taskFixture.set('Device','nod_fixture');window.taskFixture.set('Authorized repository ID','repo-second');window.taskFixture.set('Base commit','base-second');window.taskFixture.set('Published agent ID on that device','agent-second');window.taskFixture.set('Task','SECOND EXPLICIT INTENT')`)
  await click('Prepare task')
  await wait(`document.body.textContent.includes('Lost preparation reply')`)
  await check(`!window.taskFixture.hasButton('Prepare another task')`)
  await click('Retry original preparation')
  await wait(`window.taskFixture.hasButton('Start task on selected device')`)
  const secondOriginal=await run('window.taskFixture.prepared()'),allPreparations=await run(`window.taskFixture.calls().filter(c=>c.method==='chats.assignDevice')`)
  await check(`window.taskFixture.saved().some(task=>task.taskId==='${original.taskId}'&&task.status.state==='completed')`)
  await run(`window.taskFixture.failed()`);await click('Refresh task status')
  await wait(`document.body.textContent.includes('Rejected · failed')&&window.taskFixture.hasButton('Prepare another task')`)
  await click('Prepare another task')
  await wait(`!!document.querySelector('fieldset')&&!document.querySelector('fieldset').disabled`)

  await click('Refresh saved tasks')
  await wait(`!!document.querySelector('select[aria-label="Saved task"] option[value="${original.taskId}"]')`)
  await run(`window.taskFixture.set('Saved task','${original.taskId}')`)
  await wait(`window.taskFixture.hasButton('Retrieve original result')&&!document.querySelector('select[aria-label="Saved task"]').disabled`)
  await click('Retrieve original result')
  await wait(`document.body.textContent.includes('Verified result · commit')`)
  await run(`window.taskFixture.deny('cancelled')`);await click('Refresh task status')
  await wait(`document.body.textContent.includes('Rollback cancelled')`)
  await check(`!document.body.textContent.includes('verified-commit')&&!document.querySelector('textarea')&&!window.taskFixture.hasButton('Prepare another task')`)

  await run(`window.taskFixture.reset('new','chat-fixture',true)`)
  await wait(`!!document.querySelector('select[aria-label="Saved task"] option[value="${original.taskId}"]')`)
  await run(`window.taskFixture.hold();window.taskFixture.set('Saved task','${original.taskId}')`)
  await wait(`window.taskFixture.calls().some(c=>c.method==='chats.task.get')`)
  await run(`window.taskFixture.reset('new','chat-other');window.taskFixture.release()`)
  await wait(`!document.querySelector('select[aria-label="Saved task"]').disabled`)
  await check(`!document.body.textContent.includes('${original.taskId}')&&!document.body.textContent.includes('ORIGINAL INPUT')&&!document.body.textContent.includes('verified-commit')`)
  writeFileSync(config.evidence,JSON.stringify({ok:true,initialCalls,durableCalls,pageCalls,prepareCalls,lateDiscarded:true,originalFrozen:prepareCalls.every((call:any)=>JSON.stringify(call.params)===JSON.stringify(prepareCalls[0].params)),allPreparations,secondOriginal,terminalReset:true,rollbackCleared:true}))
  window.close();app.exit(0)
}catch(error){writeFileSync(config.evidence,JSON.stringify({ok:false,error:String(error),view:await run(`({devices:[...document.querySelectorAll('select[aria-label="Task device"] option')].map(option=>option.value),fields:[...document.querySelectorAll('input,textarea')].map(field=>field.value),buttons:[...document.querySelectorAll('button')].map(button=>({text:button.textContent,disabled:button.disabled}))})`)}));window.destroy();app.exit(1)}
})().catch(error=>{writeFileSync(config.evidence,JSON.stringify({ok:false,error:String(error)}));app.exit(1)})
